<script setup lang="ts">
/**
 * Filtered multiple choice (`design/components/multi-select.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/multi-select.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import {
  computed,
  onBeforeUnmount,
  onMounted,
  ref,
  shallowRef,
  useId,
  useTemplateRef,
  watch,
} from 'vue'

import * as zag from '@zag-js/combobox'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  Icon,
  afterRender,
  agentMember,
  composingKey,
  holdFieldEscape,
  lineStartKey,
  useDirection,
  useMediaQuery,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/controls/multi-select.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import MultiSelectChip from './MultiSelectChip.vue'
import Skeleton from '../structure/Skeleton.vue'

export interface MultiSelectOption {
  value: string
  label: string
  description?: string
  disabled?: boolean
}

export interface MultiSelectMessages {
  add?: (text: string) => string
  added?: (value: string, count: number) => string
  removed?: (label: string, count: number) => string
  refused?: (text: string) => string
  alreadySelected?: (value: string) => string
  selected?: (count: number, max: number | undefined) => string
  showOptions?: string
  remove?: (label: string) => string
  loadingOptions?: string
  options?: (count: number) => string
}

export interface MultiSelectProps {
  /**
   * Allows values outside `options` (the spec's boundary with TagInput). Typed text that matches
   * no option and passes `validate` appears as an extra last row, `Add "{text}"`, and choosing
   * it adds a chip. The row is removed, not disabled, when the text is empty or rejected,
   * matches an option, is already selected, or the field is full.
   */
  allowCustom?: boolean
  ariaDescribedby?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  /**
   * The initial filter text, for galleries and tests, like `defaultOpen`. The spec's States
   * table includes "open filtered", and a fixture cannot type.
   */
  defaultInputValue?: string
  /**
   * Opens on mount. For galleries and tests; screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: string[]
  disabled?: boolean
  /**
   * The empty-results text, passed in so apps can localize it (as in Combobox).
   */
  emptyMessage?: string
  /**
   * `true` filters with the locale-aware contains check (`useFilter`, based on Intl), as in
   * Combobox. `false` means **the app filtered** (async), so server results are not filtered
   * again. The mint row is never filtered out, because it is built from the text.
   */
  filter?: boolean
  id?: string
  /**
   * The controlled filter text, which async apps use to run their queries (as in Combobox). It
   * is implemented here by hand because this member uses the lower-level collection hooks.
   */
  inputValue?: string
  invalid?: boolean
  /**
   * Async loading, as in Combobox, with the same loading and empty recipes.
   */
  loading?: boolean
  /**
   * The maximum number of values, with TagInput's at-max rule. At the maximum the input becomes
   * read-only but stays focusable, labelled and announced as read-only. Backspace still removes
   * the last chip, and chips stay removable. Unchecked options are disabled. Checked options
   * stay active.
   */
  max?: number
  /**
   * The member's strings. See `MultiSelectMessages`.
   */
  messages?: MultiSelectMessages
  /**
   * Serializes as in TagInput: a comma-joined hidden input, disabled with the field.
   */
  name?: string
  /**
   * The current list, shaped as in Combobox. With async loading the app supplies it per query.
   */
  options: MultiSelectOption[]
  /**
   * Shown only while there are no chips, because the chips are the value (as in TagInput).
   */
  placeholder?: string
  /**
   * As in Combobox (`combobox.md`; the conventions' sheet presentation). `'auto'` shows the
   * popup as a sheet below `30rem`, and `'popover'` keeps the popper at every width. There is no
   * always-sheet option.
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * Normalizes or rejects custom text, as in TagInput. Return the normalized value, or `null` to
   * reject it, which hides the mint row. Options chosen from the list skip it.
   */
  validate?: (raw: string) => string | null
  /**
   * **Always in options order**: the reported array and the chips follow `options`, not click
   * order. A selection is a set, so the same choices always give the same value.
   */
  value?: string[]
}

defineOptions({ name: 'MultiSelect', inheritAttrs: false })

const props = withDefaults(defineProps<MultiSelectProps>(), {
  allowCustom: false,
  ariaRequired: undefined,
  defaultOpen: undefined,
  disabled: false,
  emptyMessage: 'No results',
  filter: true,
  invalid: false,
  loading: false,
  presentation: 'auto',
  size: 'md',
})
const emit = defineEmits<{
  blur: [event: FocusEvent]
  change: [values: string[]]
  inputChange: [value: string]
  loadMore: []
}>()
const uid = useId()
const uncontrolled = ref(props.defaultValue ?? [])
const uncontrolledText = ref(props.defaultInputValue ?? '')
const refused = ref(false)
const announcement = ref('')
const loadMoreAt = ref(-1)
const settled = ref(false)
const chipList = useTemplateRef<HTMLElement>('chipList')
const frame = useTemplateRef<HTMLElement>('frame')
const list = useTemplateRef<HTMLElement>('list')
const panel = useTemplateRef<HTMLElement>('panel')
const scrim = useTemplateRef<HTMLElement>('scrim')
const sheetPanel = useTemplateRef<HTMLElement>('sheetPanel')
const textField = useTemplateRef<HTMLElement>('textField')
const phone = useMediaQuery('phone')
const values = computed(() => props.value ?? uncontrolled.value)
const text = computed(() => props.inputValue ?? uncontrolledText.value)
const sheeting = computed(() => props.presentation === 'auto' && phone.value)
const say = computed(() => ({
  add: (text: string) => `Add "${text}"`,
  added: (value: string, count: number) => `${value} added, ${count} selected`,
  removed: (label: string, count: number) => `${label} removed, ${count} selected`,
  refused: (text: string) => `Cannot add "${text}"`,
  alreadySelected: (value: string) => `"${value}" is already selected`,
  selected: (count: number, max: number | undefined) =>
    max !== undefined && count >= max ? `Maximum of ${max} selected` : `${count} selected`,
  showOptions: 'Show options',
  remove: (label: string) => `Remove ${label}`,
  loadingOptions: 'Loading options…',
  options: (count: number) => (count === 1 ? '1 option' : `${count} options`),
  ...props.messages,
}))
const atMax = computed(() => props.max !== undefined && values.value.length >= props.max)
const countId = computed(() => `${uid}-count`)
const labels = computed(
  () => new Map(props.options.map((option) => [option.value, option.label] as const)),
)
const labelOf = computed(() => (entry: string) => labels.value.get(entry) ?? entry)
const ordered = computed(() => (chosen: ReadonlySet<string>) => [
  ...props.options.filter((option) => chosen.has(option.value)).map((option) => option.value),
  ...[...chosen].filter((entry) => !props.options.some((option) => option.value === entry)),
])
const orderedValues = computed(() => ordered.value(new Set(values.value)))
const collator = computed(
  () => new Intl.Collator(undefined, { usage: 'search', sensitivity: 'base' }),
)
const contains = computed(() => (haystack: string, needle: string) => {
  const hay = haystack.normalize('NFC')
  const pin = needle.normalize('NFC')
  for (let from = 0; from + pin.length <= hay.length; from += 1) {
    if (collator.value.compare(hay.slice(from, from + pin.length), pin) === 0) return true
  }
  return pin === ''
})
const sameText = computed(
  () => (a: string, b: string) =>
    collator.value.compare(a.normalize('NFC'), b.normalize('NFC')) === 0,
)
const shown = computed(() =>
  props.filter && text.value !== ''
    ? props.options.filter((option) => contains.value(option.label, text.value))
    : props.options,
)
const normalized = computed(() =>
  props.allowCustom && !atMax.value
    ? (props.validate ?? ((raw: string) => (raw.trim() === '' ? null : raw.trim())))(text.value)
    : null,
)
const mint = computed(() =>
  (() => {
    const candidate = normalized.value
    if (candidate === null || values.value.includes(candidate)) return null
    return props.options.some(
      (option) => option.value === candidate || sameText.value(option.label, candidate),
    )
      ? null
      : candidate
  })(),
)
const rows = computed(
  () =>
    (mint.value === null
      ? shown.value
      : [
          ...shown.value,
          { value: mint.value, label: say.value.add(mint.value) },
        ]) as MultiSelectOption[],
)
const isOff = computed(
  () => (row: MultiSelectOption) =>
    row.disabled === true || (atMax.value && !values.value.includes(row.value)),
)
const navigable = computed(() =>
  rows.value.filter((row) => !isOff.value(row)).map((row) => row.value),
)
const lastReal = computed(() => navigable.value.filter((key) => key !== mint.value).at(-1))
const commit = computed(() => (next: string[]) => {
  uncontrolled.value = next
  emit('change', next)
})
const commitText = computed(() => (next: string) => {
  uncontrolledText.value = next
  emit('inputChange', next)
})
const pick = computed(() => (chosen: string[]) => {
  const before = values.value
  const minted = mint.value
  const next = ordered.value(new Set(chosen))
  const dropped = before.filter((entry) => !next.includes(entry))
  commit.value(next)
  if (minted !== null && next.includes(minted) && !before.includes(minted)) {
    commitText.value('')
    announcement.value = say.value.added(minted, next.length)
    return
  }
  if (dropped.length > 0 && next.length < before.length) {
    announcement.value = say.value.removed(labelOf.value(dropped[0] ?? ''), next.length)
  }
})
const requestMore = computed(
  () => () =>
    !props.loading &&
    loadMoreAt.value !== props.options.length &&
    ((loadMoreAt.value = props.options.length), emit('loadMore'), true),
)
const removeButton = computed(
  () => (at: number) =>
    chipList.value?.querySelectorAll<HTMLElement>(':scope > li:not([data-removing]) button')[at] ??
    null,
)
const documentDirection = useDirection(() => frame.value)
const service = useMachine(
  {
    ...zag.machine,
    implementations: {
      ...zag.machine.implementations,
      actions: {
        ...zag.machine.implementations?.actions,
        announceHighlightedItem: (params) =>
          zag.machine.implementations?.actions?.announceHighlightedItem?.({
            ...params,
            context: {
              ...params.context,
              get: ((name: string) =>
                name === 'value'
                  ? []
                  : params.context.get(name as never)) as typeof params.context.get,
            },
          }),
      },
    },
  } as typeof zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    collection: zag.collection({
      items: rows.value,
      itemToValue: (item) => item.value,
      itemToString: (item) => item.label,
      isItemDisabled: (item) => isOff.value(item),
    }),
    multiple: true,
    value: values.value,
    inputValue: text.value,
    defaultOpen: props.defaultOpen,
    disabled: props.disabled,
    closeOnSelect: false,
    selectionBehavior: 'preserve' as const,
    allowCustomValue: true,
    positioning: { placement: 'bottom-start' as const, gutter: 2, sameWidth: false },
    ids: {
      ...(props.id === undefined ? {} : { input: props.id }),
      item: (key: string) => `${uid}-opt-${rows.value.findIndex((row) => row.value === key)}`,
    },
    onInteractOutside: (event) =>
      ((target) =>
        (frame.value?.contains(target) || panel.value?.contains(target)) && event.preventDefault())(
        event.detail.originalEvent.target as Node | null,
      ),
    onValueChange: (details) => {
      pick.value(details.value)
    },
    onInputValueChange: (details) => {
      commitText.value(details.inputValue)
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const status = computed(() =>
  !api.value.open
    ? ''
    : props.loading
      ? say.value.loadingOptions
      : rows.value.length === 0
        ? props.emptyMessage
        : say.value.options(rows.value.length),
)
const showEmpty = computed(() => api.value.open && !props.loading && rows.value.length === 0)
const aimFirst = computed(
  () => () =>
    navigable.value[0] === undefined
      ? api.value.clearHighlightValue()
      : api.value.setHighlightValue(navigable.value[0]),
)
const remove = computed(() => (entry: string) => {
  const before = orderedValues.value
  const at = before.indexOf(entry)
  const target = at === -1 || at + 1 >= before.length ? null : removeButton.value(at + 1)
  const next = before.filter((held) => held !== entry)
  commit.value(next)
  announcement.value = say.value.removed(labelOf.value(entry), next.length)
  if (target) target.focus()
  else api.value.focus()
})
const typed = computed(() => (event: Event) => {
  const input = event.target as HTMLInputElement
  const typedText = input.value
  const start = input.selectionStart
  const end = input.selectionEnd
  commitText.value(typedText)
  if (!api.value.open) api.value.setOpen(true)
  afterRender(() => {
    if (input.value !== text.value) {
      input.value = text.value
      return
    }
    queueMicrotask(() => {
      if (start === null || end === null || input.value !== typedText) return
      if (input.ownerDocument.activeElement === input) input.setSelectionRange(start, end)
    })
  })
})
const clearable = computed(() => !api.value.open && text.value !== '')
const fieldKeyDown = computed(() => (event: KeyboardEvent) => {
  if (composingKey(event)) return
  if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
    event.preventDefault()
    const down = event.key === 'ArrowDown'
    const from =
      api.value.open && api.value.highlightedValue !== null
        ? navigable.value.indexOf(api.value.highlightedValue)
        : -1
    const target =
      from === -1
        ? down
          ? navigable.value[0]
          : navigable.value[navigable.value.length - 1]
        : navigable.value[from + (down ? 1 : -1)]
    if (!api.value.open) api.value.setOpen(true)
    if (target !== undefined) api.value.setHighlightValue(target)
    return
  }
  if (event.key === 'Enter') {
    if (!api.value.open) return
    event.preventDefault()
    const highlighted = api.value.highlightedValue
    if (highlighted !== null) {
      if (navigable.value.includes(highlighted)) api.value.selectValue(highlighted)
      return
    }
    if (props.allowCustom && text.value.trim() !== '') {
      refused.value = true
      announcement.value =
        normalized.value !== null && values.value.includes(normalized.value)
          ? say.value.alreadySelected(normalized.value)
          : say.value.refused(text.value.trim())
    }
    return
  }
  if (event.key === 'Escape') {
    if (api.value.open) {
      event.preventDefault()
      api.value.setOpen(false)
      return
    }
    if (text.value !== '') {
      event.preventDefault()
      commitText.value('')
    }
    return
  }
  if (event.key === 'Backspace' && text.value === '') {
    const last = orderedValues.value[orderedValues.value.length - 1]
    if (last !== undefined) remove.value(last)
    return
  }
  // The key toward the line's start moves into the chips, as in TagInput. The direction is
  // the field's: the machine writes the document's on the input. It is a computed style, read
  // only for an arrow.
  if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return
  const input = event.target as HTMLInputElement
  if (event.key === lineStartKey(frame.value ?? input) && input.selectionStart === 0) {
    removeButton.value(orderedValues.value.length - 1)?.focus()
  }
})
const chipKeyDown = computed(() => (event: KeyboardEvent, entry: string) => {
  const at = orderedValues.value.indexOf(entry)
  if (at === -1) return
  if (event.key === 'Backspace' || event.key === 'Delete') {
    event.preventDefault()
    remove.value(entry)
    return
  }
  if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
    event.preventDefault()
    const step = event.key === lineStartKey(frame.value ?? (event.target as Element)) ? -1 : 1
    if (at + step === orderedValues.value.length) api.value.focus()
    else if (at + step >= 0) removeButton.value(at + step)?.focus()
  }
})
const toggle = computed(() => () => {
  if (props.disabled) return
  api.value.setOpen(!api.value.open)
  api.value.focus()
})
const pressField = computed(() => (event: MouseEvent) => {
  if ((event.target as HTMLElement).closest('button, input')) return
  event.preventDefault()
  api.value.focus()
})
const leave = computed(() => (event: FocusEvent) => {
  const landed = event.relatedTarget as Node | null
  if ((event.currentTarget as HTMLElement).contains(landed)) return
  if (landed !== null && panel.value?.contains(landed)) return
  if (api.value.open)
    service.send({ type: 'LAYER.INTERACT_OUTSIDE', src: 'interact-outside', restoreFocus: false })
  emit('blur', event)
})
const chipsOf = () => orderedValues.value
const chipsKey = (entry: string) => entry
const chipsLeaving = shallowRef<
  { key: string; item: ReturnType<typeof chipsOf>[number]; at: number }[]
>([])
watch(
  chipsOf,
  (now, before) => {
    const kept = new Set(now.map(chipsKey))
    const leaving = chipsLeaving.value.filter((entry) => !kept.has(entry.key))
    before.forEach((item, at) => {
      const key = chipsKey(item)
      if (!kept.has(key) && !leaving.some((entry) => entry.key === key))
        leaving.push({ key, item, at })
    })
    chipsLeaving.value = leaving
  },
  { flush: 'sync' },
)
const chips = computed(() => {
  const entries = chipsOf().map((item) => ({
    item,
    key: chipsKey(item),
    open: true,
    done: () => {},
  }))
  for (const entry of [...chipsLeaving.value].sort((a, b) => a.at - b.at))
    entries.splice(Math.min(entry.at, entries.length), 0, {
      item: entry.item,
      key: entry.key,
      open: false,
      done: () => {
        chipsLeaving.value = chipsLeaving.value.filter((other) => other.key !== entry.key)
      },
    })
  return entries
})
const present = usePresence(() => api.value.open && !sheeting.value, panel)
const sheetPresent = usePresence(
  () => api.value.open && sheeting.value,
  sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(() => api.value.open && sheeting.value, scrim, 'dialog.scrim')
const effect1 = () => {
  settled.value = true
}
onMounted(effect1)
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = clearable.value && textField.value ? holdFieldEscape(textField.value) : () => {}
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
watch(() => clearable.value, effect2, { flush: 'post' })
onBeforeUnmount(() => release2?.())
const effect3 = () => {
  api.value.open && aimFirst.value()
}
onMounted(effect3)
watch(() => text.value, effect3, { flush: 'post' })
const effect4 = () => {
  api.value.open && api.value.highlightedValue === null && aimFirst.value()
}
watch(() => api.value.open, effect4, { flush: 'post' })
const effect5 = () => {
  api.value.open &&
    api.value.highlightedValue !== null &&
    api.value.highlightedValue === lastReal.value &&
    requestMore.value()
}
onMounted(effect5)
watch(() => api.value.highlightedValue, effect5, { flush: 'post' })
let release6: (() => void) | undefined
const effect6 = () => {
  release6?.()
  const ran = agentMember({
    member: 'MultiSelect',
    element: () => textField.value,
    state: () => ({
      value: orderedValues.value,
      options: [
        ...props.options.map((option) => ({
          id: option.value,
          label: option.label,
          ...(option.disabled === true || (atMax.value && !values.value.includes(option.value))
            ? { disabled: true }
            : {}),
        })),
        ...orderedValues.value
          .filter((entry) => !labels.value.has(entry))
          .map((entry) => ({ id: entry, label: entry })),
      ],
      'input-value': text.value,
      open: api.value.open,
      disabled: props.disabled,
      invalid: props.invalid,
    }),
    actions: {
      choose: {
        argument: 'ids',
        run: (value) =>
          (() => {
            const next = ordered.value(new Set(value))
            if (props.max !== undefined && next.length > props.max)
              throw new Error(`The field holds at most ${props.max} values.`)
            if (
              next.length === orderedValues.value.length &&
              next.every((entry, at) => entry === orderedValues.value[at])
            )
              return
            commit.value(next)
          })(),
      },
      fill: {
        argument: 'text',
        run: (value) =>
          (() => {
            if (atMax.value) throw new Error('The field is full, so its text is read-only.')
            commitText.value(value)
          })(),
      },
      open: () => api.value.setOpen(true),
      close: () => api.value.setOpen(false),
    },
  })
  release6 = () => {
    ran()
  }
}
onMounted(effect6)
onBeforeUnmount(() => release6?.())
</script>

<template>
  <div
    ref="frame"
    :class="styles.field"
    :id="api.getControlProps().id"
    :data-size="size"
    :data-state="api.open ? 'open' : 'closed'"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="invalid ? '' : undefined"
    :data-loading="loading ? '' : undefined"
    :data-refused="refused ? '' : undefined"
    :data-at-max="atMax ? '' : undefined"
    :data-sheeting="sheeting && api.open ? '' : undefined"
    data-member="multi-select"
    @mousedown="pressField($event)"
    @focusout="leave($event)"
    @animationend="$event.animationName.includes('refusal') && (refused = false)"
  >
    <!-- chips -->
    <ul ref="chipList" :class="styles.chips">
      <template v-for="chip in chips" :key="chip.key">
        <MultiSelectChip
          :label="labelOf(chip.item)"
          :open="chip.open"
          :appear="settled"
          :disabled="disabled"
          :removeLabel="say.remove(labelOf(chip.item))"
          @remove="remove(chip.item)"
          @keyDown="chipKeyDown($event, chip.item)"
          @done="chip.done()"
        />
      </template>
    </ul>
    <!-- trigger -->
    <input
      ref="textField"
      v-bind="{ ...api.getInputProps(), onKeydown: fieldKeyDown, onInput: typed }"
      :class="styles.input"
      :placeholder="values.length === 0 ? placeholder : undefined"
      :readonly="atMax"
      :aria-controls="api.open ? api.getContentProps().id : undefined"
      :aria-label="ariaLabel"
      :aria-labelledby="ariaLabelledby"
      :aria-describedby="[ariaDescribedby, countId].filter(Boolean).join(' ')"
      :aria-required="ariaRequired"
      :aria-invalid="invalid ? true : undefined"
    />
    <!-- chevron -->
    <button
      v-bind="{ ...api.getTriggerProps(), onClick: undefined, onPointerdown: undefined }"
      :class="styles.chevron"
      :aria-label="say.showOptions"
      @mousedown="($event.preventDefault(), toggle())"
      @click="$event.detail === 0 && toggle()"
    >
      <span v-if="loading" :class="styles.spinner">
        <Icon name="loading" :size="size" />
      </span>
      <Icon v-else name="expand" :size="size" />
    </button>
    <!-- count -->
    <span :class="styles.reader" :id="countId">
      {{ say.selected(values.length, max) }}
    </span>
    <!-- announcer -->
    <span :class="styles.reader" aria-live="polite">
      {{ announcement }}
    </span>
    <div :class="styles.status" role="status" aria-live="polite">
      {{ status }}
    </div>
    <input
      v-if="name !== undefined"
      type="hidden"
      :name="name"
      :value="orderedValues.join(',')"
      :disabled="disabled"
    />
  </div>
  <Teleport to="body">
    <div v-if="present" v-bind="api.getPositionerProps()">
      <!-- panel -->
      <div
        ref="panel"
        :class="styles.content"
        :style="{
          '--radix-popover-trigger-width': 'var(--reference-width)',
          '--radix-popover-content-available-height': 'var(--available-height)',
          '--radix-popover-content-transform-origin': 'var(--transform-origin)',
        }"
        :data-size="size"
        :data-state="api.open ? 'open' : 'closed'"
        data-member="multi-select"
      >
        <!-- list -->
        <ul
          ref="list"
          v-bind="api.getContentProps()"
          :class="styles.listbox"
          :hidden="undefined"
          :aria-label="ariaLabelledby === undefined ? ariaLabel : undefined"
          :aria-labelledby="ariaLabelledby"
          @scroll="
            (list?.scrollHeight ?? 0) - (list?.scrollTop ?? 0) - (list?.clientHeight ?? 0) <= 32 &&
            requestMore()
          "
        >
          <template v-for="(row, at) in rows" :key="row.value">
            <!-- option -->
            <li
              v-bind="api.getItemProps({ item: row })"
              :class="styles.option"
              :aria-selected="values.includes(row.value) ? 'true' : 'false'"
              :aria-labelledby="`${uid}-opt-${at}` + '-label'"
              :aria-describedby="
                row.description !== undefined ? `${uid}-opt-${at}` + '-description' : undefined
              "
              :data-mint="row.value === mint ? '' : undefined"
            >
              <span :class="styles.check">
                <Icon v-if="row.value === mint" name="add" size="sm" />
                <Icon v-else-if="values.includes(row.value)" name="confirm" size="sm" />
              </span>
              <span :class="styles.text">
                <span :class="styles.optionLabel" :id="`${uid}-opt-${at}` + '-label'">
                  {{ row.label }}
                </span>
                <span
                  v-if="row.description !== undefined"
                  :class="styles.description"
                  :id="`${uid}-opt-${at}` + '-description'"
                >
                  {{ row.description }}
                </span>
              </span>
            </li>
          </template>
        </ul>
        <div v-if="loading" :class="styles.rows" aria-hidden="true">
          <template v-for="row in [0, 1, 2]" :key="row">
            <div :class="styles.row">
              <Skeleton textStep="sm" />
            </div>
          </template>
        </div>
        <div v-if="showEmpty" :class="styles.empty" aria-hidden="true">
          {{ emptyMessage }}
        </div>
      </div>
    </div>
    <div
      v-if="scrimPresent"
      ref="scrim"
      :class="sheet.scrim"
      :data-state="api.open ? 'open' : 'closed'"
    />
    <div v-if="sheetPresent" :class="sheet.positioner">
      <div
        ref="sheetPanel"
        :class="sheet.panel"
        data-presentation="sheet"
        :data-state="api.open ? 'open' : 'closed'"
      >
        <!-- panel -->
        <div ref="panel" :class="styles.sheetBody" :data-size="size" data-member="multi-select">
          <!-- list -->
          <ul
            ref="list"
            v-bind="api.getContentProps()"
            :class="styles.listbox"
            :hidden="undefined"
            :aria-label="ariaLabelledby === undefined ? ariaLabel : undefined"
            :aria-labelledby="ariaLabelledby"
            @scroll="
              (list?.scrollHeight ?? 0) - (list?.scrollTop ?? 0) - (list?.clientHeight ?? 0) <=
                32 && requestMore()
            "
          >
            <template v-for="(row, at) in rows" :key="row.value">
              <!-- option -->
              <li
                v-bind="api.getItemProps({ item: row })"
                :class="styles.option"
                :aria-selected="values.includes(row.value) ? 'true' : 'false'"
                :aria-labelledby="`${uid}-opt-${at}` + '-label'"
                :aria-describedby="
                  row.description !== undefined ? `${uid}-opt-${at}` + '-description' : undefined
                "
                :data-mint="row.value === mint ? '' : undefined"
              >
                <span :class="styles.check">
                  <Icon v-if="row.value === mint" name="add" size="sm" />
                  <Icon v-else-if="values.includes(row.value)" name="confirm" size="sm" />
                </span>
                <span :class="styles.text">
                  <span :class="styles.optionLabel" :id="`${uid}-opt-${at}` + '-label'">
                    {{ row.label }}
                  </span>
                  <span
                    v-if="row.description !== undefined"
                    :class="styles.description"
                    :id="`${uid}-opt-${at}` + '-description'"
                  >
                    {{ row.description }}
                  </span>
                </span>
              </li>
            </template>
          </ul>
          <div v-if="loading" :class="styles.rows" aria-hidden="true">
            <template v-for="row in [0, 1, 2]" :key="row">
              <div :class="styles.row">
                <Skeleton textStep="sm" />
              </div>
            </template>
          </div>
          <div v-if="showEmpty" :class="styles.empty" aria-hidden="true">
            {{ emptyMessage }}
          </div>
        </div>
      </div>
    </div>
  </Teleport>
</template>
